Array accepted_templates(const Dictionary &normalized_config) {
	Array accepted;
	const int32_t score = size_score(normalized_config);
	const int32_t humans = human_count(normalized_config);
	const int32_t players = player_count(normalized_config);
	if (!supports_scope(normalized_config)) {
		return accepted;
	}
	if (supports_small_land_scope(normalized_config)) {
		for (const TemplateEvidence &candidate : SMALL_LAND_TEMPLATES) {
			if (score < candidate.min_size_score || score > candidate.max_size_score) {
				continue;
			}
			if (humans < candidate.min_humans || humans > candidate.max_humans || players < candidate.min_total_players || players > candidate.max_total_players || players < humans) {
				continue;
			}
			accepted.append(template_record(candidate));
		}
		return accepted;
	}
	Dictionary catalog_load = load_compiled_template_catalog();
	if (!bool(catalog_load.get("ok", false))) {
		return accepted;
	}
	Dictionary catalog = catalog_load.get("data", Dictionary());
	if (Variant(catalog.get("templates", Variant())).get_type() != Variant::ARRAY) {
		return accepted;
	}
	Array templates = catalog.get("templates", Array());
	for (int64_t template_index = 0; template_index < templates.size(); ++template_index) {
		if (Variant(templates[template_index]).get_type() != Variant::DICTIONARY) {
			continue;
		}
		Dictionary source = templates[template_index];
		Dictionary provenance = source.get("import_provenance", Dictionary());
		const int32_t imported_source_index = int32_t(provenance.get("source_template_index", -1));
		const bool imported_schema = imported_source_index > 0;
		Dictionary record = imported_schema
				? template_record_from_imported_catalog(source, int32_t(template_index), humans, players)
				: template_record_from_recovered_catalog(source, int32_t(template_index), humans, players);
		if (score < int32_t(record.get("min_size_score", 0)) || score > int32_t(record.get("max_size_score", 0))) {
			continue;
		}
		if (humans < int32_t(record.get("min_humans", 0)) || humans > int32_t(record.get("max_humans", 0)) || players < int32_t(record.get("min_total_players", 0)) || players > int32_t(record.get("max_total_players", 0)) || players < humans) {
			continue;
		}
		if (!supports_medium_land_scope(normalized_config) && !template_record_supports_requested_players(record, humans, players)) {
			continue;
		}
		accepted.append(record);
	}
	return accepted;
}

Dictionary binary_verification() {
	Dictionary report;
	report["source"] = COMPILED_H3MAPED_DATA_SOURCE;
	report["reference_sha256"] = H3MAPED_REFERENCE_SHA256;
	report["reference_size_bytes"] = H3MAPED_REFERENCE_SIZE_BYTES;
	report["format"] = "compiled recovered h3maped RMG tables";
	report["template_catalog_bytes"] = int64_t(embedded_data::random_map_template_catalog_json_size());
	report["object_catalog_bytes"] = int64_t(embedded_data::object_catalog_by_type_json_size());
	report["decoration_obstacles_bytes"] = int64_t(embedded_data::decoration_obstacles_csv_size());
	report["reward_proxy_catalog_bytes"] = int64_t(embedded_data::reward_proxy_catalog_json_size());
	report["monster_candidate_summary_bytes"] = int64_t(embedded_data::monster_candidate_summary_json_size());
	report["ok"] = embedded_data::random_map_template_catalog_json_size() > 0
			&& embedded_data::object_catalog_by_type_json_size() > 0
			&& embedded_data::decoration_obstacles_csv_size() > 0
			&& embedded_data::reward_proxy_catalog_json_size() > 0
			&& embedded_data::monster_candidate_summary_json_size() > 0;
	report["status"] = bool(report["ok"]) ? String("compiled_data_ready") : String("compiled_data_missing");
	return report;
}

std::vector<std::vector<String>> parse_h3maped_tsv(const String &text) {
	std::vector<std::vector<String>> rows;
	std::vector<String> row;
	String field;
	bool quoted = false;
	for (int64_t index = 0; index < text.length(); ++index) {
		const char32_t ch = text[index];
		if (ch == '"') {
			if (quoted && index + 1 < text.length() && text[index + 1] == '"') {
				field += String::chr('"');
				++index;
			} else {
				quoted = !quoted;
			}
			continue;
		}
		if (!quoted && ch == '\t') {
			row.push_back(field);
			field = String();
			continue;
		}
		if (!quoted && (ch == '\n' || ch == '\r')) {
			if (ch == '\r' && index + 1 < text.length() && text[index + 1] == '\n') {
				++index;
			}
			row.push_back(field);
			rows.push_back(row);
			row.clear();
			field = String();
			continue;
		}
		field += String::chr(ch);
	}
	if (field.length() > 0 || !row.empty()) {
		row.push_back(field);
		rows.push_back(row);
	}
	return rows;
}

bool parse_int_field(const String &value, int32_t &out_value) {
	const String stripped = value.strip_edges();
	if (stripped.is_empty()) {
		return false;
	}
	const CharString utf8 = stripped.utf8();
	char *end = nullptr;
	errno = 0;
	const long parsed = std::strtol(utf8.get_data(), &end, 10);
	if (errno != 0 || end == utf8.get_data() || *end != '\0') {
		return false;
	}
	out_value = int32_t(parsed);
	return true;
}

std::vector<std::pair<int32_t, int32_t>> h3maped_crtraits_monster_row_walk() {
	static constexpr int32_t GROUP_COUNTS[] = { 14, 14, 14, 14, 14, 14, 14, 14, 6, 14, 13 };
	std::vector<std::pair<int32_t, int32_t>> rows;
	int32_t monster_index = 0;
	int32_t source_row_index = 2;
	for (const int32_t group_count : GROUP_COUNTS) {
		for (int32_t index = 0; index < group_count; ++index) {
			rows.push_back(std::make_pair(monster_index, source_row_index));
			++monster_index;
			++source_row_index;
		}
		source_row_index += 3;
	}
	for (int32_t index = 0; index < 5; ++index) {
		rows.push_back(std::make_pair(monster_index, source_row_index));
		++monster_index;
		++source_row_index;
	}
	return rows;
}

