bool player_filter_allows(const Dictionary &filter, int32_t humans, int32_t players) {
	return humans >= int32_t(filter.get("min_human", 0))
			&& humans <= int32_t(filter.get("max_human", 8))
			&& players >= int32_t(filter.get("min_total", 0))
			&& players <= int32_t(filter.get("max_total", 8));
}

Dictionary runtime_zone_relation_lookup_0x49b3fb_phase(const Array &link_seeds) {
	Dictionary phase;
	phase["phase_id"] = "runtime_zone_relation_lookup_0x49b3fb";
	phase["status"] = "active_strict_relation_vectors_0x49b3fb";
	phase["h3maped_anchor"] = "0x49b3fb";
	phase["source"] = "reciprocal runtime-zone relation records built from recovered 0x4a1f3b link seeds before 0x4a8c15 relation consumers";
	phase["materializes_connection_guards"] = false;
	phase["materializes_blockers"] = false;
	phase["materializes_public_output"] = false;
	Dictionary relation_vectors;
	int32_t relation_record_count = 0;
	int32_t relation_wide_byte_8_count = 0;
	auto append_relation = [&](int32_t owner_relation_key, int32_t neighbor_relation_key, int32_t owner_zone_word_id, int32_t neighbor_zone_word_id, int32_t runtime_zone, int32_t neighbor_runtime_zone, const Dictionary &seed) {
		if (owner_relation_key < 0 || neighbor_relation_key < 0) {
			return;
		}
		const String key = String::num_int64(owner_relation_key);
		Array records = relation_vectors.get(key, Array());
		Dictionary relation;
		relation["relation_owner_key"] = owner_relation_key;
		relation["relation_neighbor_key"] = neighbor_relation_key;
		relation["owner_zone_word_id"] = owner_zone_word_id;
		relation["neighbor_zone_word_id"] = neighbor_zone_word_id;
		relation["first_dword_zone_word_id"] = neighbor_zone_word_id;
		relation["owner_runtime_zone"] = runtime_zone;
		relation["neighbor_runtime_zone"] = neighbor_runtime_zone;
		relation["first_dword_runtime_zone"] = neighbor_runtime_zone;
		relation["byte_plus_8_wide"] = bool(seed.get("wide", false)) ? 1 : 0;
		relation["wide"] = bool(seed.get("wide", false));
		relation["border_guard"] = bool(seed.get("border_guard", false));
		relation["guard_value"] = seed.get("guard_value", 0);
		relation["link_index"] = seed.get("link_index", -1);
		relation["source_row"] = seed.get("source_row", -1);
		relation["h3maped_lookup_anchor"] = "0x49b3fb";
		records.append(relation);
		relation_vectors[key] = records;
		relation_record_count += 1;
		if (bool(seed.get("wide", false))) {
			relation_wide_byte_8_count += 1;
		}
	};
	auto append_relation_aliases = [&](int32_t source_a, int32_t source_b, int32_t runtime_a, int32_t runtime_b, const Dictionary &seed) {
		append_relation(source_a, source_b, source_a, source_b, runtime_a, runtime_b, seed);
		if (runtime_a != source_a || runtime_b != source_b) {
			append_relation(runtime_a, runtime_b, source_a, source_b, runtime_a, runtime_b, seed);
		}
	};
	for (int64_t relation_index = 0; relation_index < link_seeds.size(); ++relation_index) {
		if (Variant(link_seeds[relation_index]).get_type() != Variant::DICTIONARY) {
			continue;
		}
		Dictionary seed = link_seeds[relation_index];
		const int32_t runtime_a = int32_t(seed.get("runtime_zone_a", -1));
		const int32_t runtime_b = int32_t(seed.get("runtime_zone_b", -1));
		const int32_t source_a = int32_t(seed.get("source_zone_a", runtime_a));
		const int32_t source_b = int32_t(seed.get("source_zone_b", runtime_b));
		append_relation_aliases(source_a, source_b, runtime_a, runtime_b, seed);
		append_relation_aliases(source_b, source_a, runtime_b, runtime_a, seed);
	}
	phase["link_seed_count"] = link_seeds.size();
	phase["runtime_zone_relation_vectors_0x49b3fb"] = relation_vectors;
	phase["runtime_zone_relation_record_count_0x49b3fb"] = relation_record_count;
	phase["runtime_zone_relation_wide_byte_8_count_0x49b3fb"] = relation_wide_byte_8_count;
	return phase;
}

Dictionary link_seed_phase(const Dictionary &normalized_config, const Dictionary &selection, const Dictionary &runtime_zone_phase) {
	Dictionary phase;
	phase["phase_id"] = "link_seed_setup";
	phase["status"] = "blocked_until_runtime_zone_records";
	phase["h3maped_anchor"] = "0x4a1f3b";
	phase["candidate_generator_anchor"] = "0x4a17f5";
	phase["distance_validation_anchor"] = "0x4a1701";
	phase["late_payload_consumer_anchor"] = "0x4a79a3";
	phase["materializes_coordinates"] = false;
	phase["materializes_connection_guards"] = false;
	phase["materializes_roads"] = false;
	phase["materializes_blockers"] = false;
	phase["materializes_public_output"] = false;
	phase["blocked_next"] = "coordinate_replay_0x4a17f5_0x4a1701";
	const String runtime_status = String(runtime_zone_phase.get("status", ""));
	if (runtime_status != "active_internal_state" && runtime_status != "active_strict_executable_port") {
		return phase;
	}

	Dictionary catalog_load;
	Dictionary original_template = find_original_h3maped_template_record(selection, catalog_load);
	phase["original_template_catalog_load"] = catalog_load;
	phase["project_template_bridge_enabled"] = false;
	Variant connection_value = original_template.get("connections", original_template.get("links", Variant()));
	if (original_template.is_empty() || connection_value.get_type() != Variant::ARRAY) {
		phase["status"] = "blocked_missing_original_h3maped_template_connections";
		return phase;
	}

	const int32_t humans = human_count(normalized_config);
	const int32_t players = player_count(normalized_config);
	Dictionary runtime_index_by_source_zone_id;
	Array runtime_records = runtime_zone_phase.get("runtime_zone_records", Array());
	for (int64_t index = 0; index < runtime_records.size(); ++index) {
		if (Variant(runtime_records[index]).get_type() != Variant::DICTIONARY) {
			continue;
		}
		Dictionary runtime = runtime_records[index];
		const int32_t source_zone_id = int32_t(runtime.get("source_zone_id", -1));
		if (source_zone_id > 0) {
			runtime_index_by_source_zone_id[String::num_int64(source_zone_id)] = runtime.get("runtime_zone_index", runtime.get("runtime_index", index));
		}
	}
	Array links = connection_value;
	Array seeds;
	for (int64_t index = 0; index < links.size(); ++index) {
		if (Variant(links[index]).get_type() != Variant::DICTIONARY) {
			continue;
		}
		Dictionary link = links[index];
		if (!player_filter_allows(link.get("player_filter", Dictionary()), humans, players)) {
			continue;
		}
		Dictionary endpoints = link.get("source_endpoints", Dictionary());
		const int32_t source_zone_a = int32_t(link.get("zone1", endpoints.get("zone1", 0)));
		const int32_t source_zone_b = int32_t(link.get("zone2", endpoints.get("zone2", 0)));
		if (source_zone_a <= 0 || source_zone_b <= 0) {
			continue;
		}
		Dictionary guard = link.get("guard", Dictionary());
		Dictionary grammar_source = link.get("grammar_source", Dictionary());
		Dictionary seed;
		seed["link_index"] = seeds.size();
		seed["source_row"] = link.get("row", grammar_source.get("source_row", -1));
		seed["source_zone_a"] = source_zone_a;
		seed["source_zone_b"] = source_zone_b;
		seed["runtime_zone_a"] = runtime_index_by_source_zone_id.get(String::num_int64(source_zone_a), source_zone_a - 1);
		seed["runtime_zone_b"] = runtime_index_by_source_zone_id.get(String::num_int64(source_zone_b), source_zone_b - 1);
		seed["guard_value"] = link.get("value", link.get("guard_value", guard.get("value", 0)));
		seed["wide"] = bool(link.get("wide", false));
		seed["border_guard"] = bool(link.get("border_guard", false));
		seed["early_consumer"] = "0x4a1f3b_endpoint_only";
		seed["late_payload_consumer"] = "0x4a79a3";
		seeds.append(seed);
	}

	phase["status"] = "active_internal_state";
	phase["source"] = "original recovered h3maped rmg-template-catalog.json connections consumed through h3maped 0x4a1f3b";
	phase["original_template_name"] = original_template.get("name", "");
	phase["link_seed_count"] = seeds.size();
	phase["link_seeds"] = seeds;
	Dictionary relation_lookup = runtime_zone_relation_lookup_0x49b3fb_phase(seeds);
	phase["runtime_zone_relation_lookup_0x49b3fb"] = relation_lookup;
	phase["runtime_zone_relation_vectors_0x49b3fb"] = relation_lookup.get("runtime_zone_relation_vectors_0x49b3fb", Dictionary());
	phase["runtime_zone_relation_record_count_0x49b3fb"] = relation_lookup.get("runtime_zone_relation_record_count_0x49b3fb", 0);
	phase["runtime_zone_relation_wide_byte_8_count_0x49b3fb"] = relation_lookup.get("runtime_zone_relation_wide_byte_8_count_0x49b3fb", 0);
	return phase;
}

int32_t h3maped_distance_truncate_local(int32_t ax, int32_t ay, int32_t bx, int32_t by) {
	const int64_t dx = int64_t(ax) - int64_t(bx);
	const int64_t dy = int64_t(ay) - int64_t(by);
	return int32_t(std::trunc(std::sqrt(double(dx * dx + dy * dy))));
}

std::vector<H3MaskPoint> h3_text_mask_points(const String &mask_text, bool action_mask) {
	std::vector<H3MaskPoint> points;
	if (mask_text.length() < 48) {
		return points;
	}
	for (int32_t row = 0; row < H3MAPED_OBJECT_MASK_ROWS; ++row) {
		for (int32_t text_col = 0; text_col < H3MAPED_OBJECT_MASK_COLUMNS; ++text_col) {
			const bool bit_set = mask_text[row * H3MAPED_OBJECT_MASK_COLUMNS + text_col] == '1';
			const bool include = action_mask ? bit_set : !bit_set;
			if (!include) {
				continue;
			}
			points.push_back(H3MaskPoint { -text_col, -((H3MAPED_OBJECT_MASK_ROWS - 1) - row) });
		}
	}
	return points;
}

H3MaskPoint h3_object_row_origin_0x2c_0x30_from_action_mask(const String &action_mask) {
	if (action_mask.length() < H3MAPED_OBJECT_MASK_COLUMNS * H3MAPED_OBJECT_MASK_ROWS) {
		return H3MaskPoint { 0, 0 };
	}
	for (int32_t local_y = 0; local_y < H3MAPED_OBJECT_MASK_ROWS; ++local_y) {
		for (int32_t local_x = 0; local_x < H3MAPED_OBJECT_MASK_COLUMNS; ++local_x) {
			if (action_mask[local_y * H3MAPED_OBJECT_MASK_COLUMNS + local_x] == '1') {
				return H3MaskPoint { local_x, local_y };
			}
		}
	}
	return H3MaskPoint { 0, 0 };
}

std::vector<H3MaskPoint> h3_msk_mask_points_0x49e1bf(uint64_t mask, int32_t width_0x34, int32_t height_0x38) {
	std::vector<H3MaskPoint> points;
	const int32_t width = std::max<int32_t>(0, std::min<int32_t>(width_0x34, H3MAPED_OBJECT_MASK_COLUMNS));
	const int32_t height = std::max<int32_t>(0, std::min<int32_t>(height_0x38, H3MAPED_OBJECT_MASK_ROWS));
	for (int32_t local_y = 0; local_y < height; ++local_y) {
		for (int32_t local_x = 0; local_x < width; ++local_x) {
			const int32_t bit_index = (H3MAPED_OBJECT_MASK_COLUMNS * H3MAPED_OBJECT_MASK_ROWS - 1)
					- (local_y * H3MAPED_OBJECT_MASK_COLUMNS)
					- local_x;
			if (bit_index < 0 || bit_index >= 64) {
				continue;
			}
			if (((mask >> uint32_t(bit_index)) & 1ULL) == 0ULL) {
				continue;
			}
			// 0x49e1bf scores mask-A cells as selected_x - 2 + local_x and
			// selected_y - local_y. The later 0x49abd6 stamp frame is separate
			// and still writes object body cells at selected_x - local_x.
			points.push_back(H3MaskPoint { local_x - 2, -local_y });
		}
	}
	return points;
}

bool h3_object_row_mask_bit_0x41e915(uint64_t mask, int32_t local_x, int32_t local_y) {
	if (local_x < 0 || local_y < 0 || local_x >= H3MAPED_OBJECT_MASK_COLUMNS || local_y >= H3MAPED_OBJECT_MASK_ROWS) {
		return false;
	}
	const int32_t bit_index = (H3MAPED_OBJECT_MASK_COLUMNS * H3MAPED_OBJECT_MASK_ROWS - 1)
			- (local_y * H3MAPED_OBJECT_MASK_COLUMNS)
			- local_x;
	if (bit_index < 0 || bit_index >= 64) {
		return false;
	}
	return ((mask >> uint32_t(bit_index)) & 1ULL) != 0ULL;
}

