int32_t h3_monster_candidate_quantity_bucket(int32_t raw_value) {
	if (raw_value > 50) {
		return ((raw_value + 5) / 10) * 10;
	}
	if (raw_value > 12) {
		return ((raw_value + 2) / 5) * 5;
	}
	if (raw_value > 5) {
		return ((raw_value + 1) / 2) * 2;
	}
	return raw_value;
}

